CREATE OR REPLACE PROCEDURE sp(
    para_Start_year integer,
    para_Club_name text,
    para_Club_ID integer,
    para_Player_ID integer,
    para_Occupation text,
    para_Votes integer
)
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE club
       SET Club_name = 'phase_9',
           Region = CASE WHEN Start_year < para_Start_year THEN para_Club_name ELSE Region END;

    DELETE FROM club WHERE Club_ID <= para_Club_ID + 7;

    DELETE FROM player WHERE Votes < para_Votes;

    UPDATE player SET Occupation = 'log_phase_9';

    IF EXISTS (SELECT 1 FROM player WHERE Player_ID = para_Player_ID) THEN
        UPDATE player SET Sponsor_name = para_Occupation WHERE Player_ID = para_Player_ID;
    ELSE
        UPDATE player SET Sponsor_name = para_Club_name;
    END IF;
END;
$$;

CALL sp(2008, 'region_c4', -4, 5, 'sponsor_p5', 9491);
SELECT 'club' AS t, Club_ID, Club_name, Region, Start_year FROM club ORDER BY Club_ID;
SELECT 'player' AS t, Player_ID, Sponsor_name, Player_name, Gender, Residence, Occupation, Votes, Rank FROM player ORDER BY Player_ID;

